	'messages:apihelp-query+redirects-paramvalue-prop-pageid' => 'ru:Идентификатор каждого перенаправления.',
	'messages:apihelp-query+redirects-paramvalue-prop-title' => 'ru:Название каждого перенаправления.',
	'messages:apihelp-query+redirects-paramvalue-prop-fragment' => 'ru:Фрагемнт каждого перенаправления, если доступен.',
	'messages:apihelp-query+redirects-param-namespace' => 'ru:Включить страницы только из данных пространств имён.',
	'messages:apihelp-query+redirects-param-show' => 'ru:Показывать только элементы, удовлетворяющие данным критериям:',
	'messages:apihelp-query+redirects-paramvalue-show-fragment' => 'ru:Показывать только перенаправления с фрагментами.',
